using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in config or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<Notebook>();
builder.Services.AddSingleton<ResearchRunner>();

var host = builder.Build();
var runner = host.Services.GetRequiredService<ResearchRunner>();

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.Error.WriteLine("No topic provided.");
    return;
}

await runner.RunAsync(topic);

// ── Research runner ──────────────────────────────────────────────────

sealed class ResearchRunner(IChatClient chatClient, Notebook notebook)
{
    public async Task RunAsync(string topic)
    {
        Console.WriteLine($"\n🔍 Researching: {topic}\n");

        var tools = new AIToolCollection
        {
            AIFunctionFactory.Create(SearchWeb),
            AIFunctionFactory.Create(notebook.SaveNote),
            AIFunctionFactory.Create(notebook.GetNotes),
        };

        var agent = new ChatClientAgent(chatClient,
            $"""
            You are a research assistant. Your goal is to thoroughly research a given topic and produce a clear summary.

            Follow these steps:
            1. Search the web for the topic to gather information from multiple angles.
            2. Save important findings as notes using the note-taking tool.
            3. Review your collected notes.
            4. Produce a final, well-structured summary of your research.

            Be thorough but concise. Cite key facts. Save at least 3 notes before summarizing.
            """);

        var options = new AgentInvokeOptions
        {
            MaximumIterations = 15,
            Tools = tools,
            Temperature = 0f,
        };

        var history = new List<ChatMessage>
        {
            new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
        };

        await foreach (var message in agent.InvokeStreamingAsync(history, options))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
            {
                Console.Write(message.Text);
            }
        }

        Console.WriteLine("\n\n── Saved Notes ────────────────────────────────────");
        foreach (var note in notebook.GetAllNotes())
        {
            Console.WriteLine($"• {note}");
        }
        Console.WriteLine("───────────────────────────────────────────────────");
    }

    [Description("Search the web for a query and return relevant results as text snippets.")]
    static async Task<string> SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        try
        {
            using var http = new HttpClient();
            http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");
            // Use DuckDuckGo Instant Answer API (no API key required)
            var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1&skip_disambig=1";
            var response = await http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            if (response.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
                results.Add($"Summary: {abstractText}");
            if (response.TryGetProperty("AbstractSource", out var src) && src.GetString() is { Length: > 0 } source)
                results.Add($"Source: {source}");

            if (response.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                        results.Add($"- {t}");
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing or breaking into sub-queries.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

