sealed class ResearchRunner(IChatClient chatClient, Notebook notebook)
{
    public async Task RunAsync(string topic)
    {
        Console.WriteLine($"\n🔍 Researching: {topic}\n");

        var tools = new AIToolCollection
        {
            AIFunctionFactory.Create(SearchWeb),
            AIFunctionFactory.Create(notebook.SaveNote),
            AIFunctionFactory.Create(notebook.GetNotes),
        };

        var agent = new ChatClientAgent(chatClient,
            $"""
            You are a research assistant. Your goal is to thoroughly research a given topic and produce a clear summary.

            Follow these steps:
            1. Search the web for the topic to gather information from multiple angles.
            2. Save important findings as notes using the note-taking tool.
            3. Review your collected notes.
            4. Produce a final, well-structured summary of your research.

            Be thorough but concise. Cite key facts. Save at least 3 notes before summarizing.
            """);

        var options = new AgentInvokeOptions
        {
            MaximumIterations = 15,
            Tools = tools,
            Temperature = 0f,
        };

        var history = new List<ChatMessage>
        {
            new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
        };

        await foreach (var message in agent.InvokeStreamingAsync(history, options))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
            {
                Console.Write(message.Text);
            }
        }

        Console.WriteLine("\n\n── Saved Notes ────────────────────────────────────");
        foreach (var note in notebook.GetAllNotes())
        {
            Console.WriteLine($"• {note}");
        }
        Console.WriteLine("───────────────────────────────────────────────────");
    }

    [Description("Search the web for a query and return relevant results as text snippets.")]
    static async Task<string> SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
