            var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1&skip_disambig=1";
            var response = await http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            if (response.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
                results.Add($"Summary: {abstractText}");
            if (response.TryGetProperty("AbstractSource", out var src) && src.GetString() is { Length: > 0 } source)
                results.Add($"Source: {source}");

            if (response.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                        results.Add($"- {t}");
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing or breaking into sub-queries.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

